        shayariItem(270, "भरोसा एक शीशा है जो टूट जाए तो जुड़ता नहीं,\nऔर जुड़ भी जाए तो दरारें हमेशा दिखती हैं।", "_ शायरी", cat, "दरार"),
        shayariItem(271, "बेवफ़ाई की आग में जलकर भी हम ख़ाक न हुए,\nक्योंकि तेरे जाने के बाद ही हमें खुद की कीमत समझ आई।", "_ शायरी", cat, "ख़ुद्दारी"),
        shayariItem(272, "कभी वक़्त मिले तो अपने गिरेबान में झाँक लेना,\nतुमने क्या खोया है ये ख़ुद ही समझ आ जाएगा।", "_ शायरी", cat, "एहसास"),
        shayariItem(273, "हमें छोड़ने की वजह तो बता जाते कम से कम,\nताकि हम अपनी कमियों को ही दोष दे पाते।", "_ शायरी", cat, "वजह"),
        shayariItem(274, "तेरे शहर में अब हमारी कोई ज़रूरत नहीं,\nजहाँ कद्र न हो वहाँ रुकना भी फ़िज़ूल है।", "_ शायरी", cat, "कद्र"),
        shayariItem(275, "वो लोग भी मोहब्बत के दावे करते हैं,\nजिन्हें एक चेहरे पर टिकना भी नहीं आता।", "_ शायरी", cat, "दावे"),
        shayariItem(276, "ज़िंदगी की सबसे बड़ी सीख यही मिली है,\nअंधा भरोसा हमेशा आँखों में आँसू देता है।", "_ शायरी", cat, "सीख"),
        shayariItem(277, "दिल से उतर जाने के बाद कोई कितना भी मनाए,\nपहले जैसी जगह फिर कभी नहीं बनती।", "_ शायरी", cat, "दिल"),
        shayariItem(278, "हमने तो हर दुआ में तुम्हारी ख़ुशी माँगी थी,\nऔर तुमने मेरी ख़ुशियों का ही गला घोंट दिया।", "_ शायरी", cat, "दुआ"),
        shayariItem(279, "झूठे आंसुओं का कारोबार अच्छा चलाया तुमने,\nपर अफ़सोस कि असली जज़्बात पहचान न पाए।", "_ शायरी", cat, "जज़्बात"),
        shayariItem(280, "राख हो गए अरमान सारे तेरे इंतजार में,\nऔर तू बेख़बर किसी और की बहारों में खो गया।", "_ शायरी", cat, "अरमान"),
        shayariItem(281, "जिस पर सबसे ज़्यादा नाज़ था हमें,\nउसने ही सर झुकाने पर मजबूर कर दिया।", "_ शायरी", cat, "नाज़"),
        shayariItem(282, "तुम्हारे बिना भी दिन कट ही जाते हैं अब,\nबस शाम ढलते ही पुराना दर्द जाग जाता है।", "_ शायरी", cat, "शाम"),
        shayariItem(283, "दोस्ती हो या प्यार अगर नीयत साफ़ न हो,\nतो हर रिश्ता कुछ दिनों का मेहमान होता है।", "_ शायरी", cat, "नीयत"),
        shayariItem(284, "हमने चाँद समझकर जिसे रातों को देखा,\nवो तो सुबह होते ही बादलों में गुम हो गया।", "_ शायरी", cat, "चाँद"),
        shayariItem(285, "इतनी सस्ती नहीं थी मेरी मोहब्बत जनाब,\nबस तुमने कद्र करने की तमीज़ नहीं सीखी।", "_ शायरी", cat, "अंदाज़"),
        shayariItem(286, "जहाँ वफ़ा की उम्मीद सबसे ज़्यादा थी,\nवहीं से सबसे बड़ा सदमा मिला।", "_ शायरी", cat, "सदमा"),
        shayariItem(287, "लफ़्ज़ों की बाज़ीगरी से दिल जीत लिया तुमने,\nकाश किरदार भी उतना ही सच्चा रखा होता।", "_ शायरी", cat, "लफ़्ज़"),
        shayariItem(288, "अब पलटकर मत आना मेरी ज़िंदगी में,\nजो दिल तोड़ा था वो अब पत्थर बन चुका है।", "_ शायरी", cat, "पत्थर दिल"),
        shayariItem(289, "हर किसी की क़िस्मत में सच्चा प्यार नहीं होता,\nकुछ लोग सिर्फ़ सबक सिखाने के लिए मिलते हैं।", "_ शायरी", cat, "क़िस्मत"),
        shayariItem(290, "तुम्हारे झूठे प्यार से लाख गुना बेहतर है,\nमेरा ये सच्चा और ख़ामोश अकेलापन।", "_ शायरी", cat, "अकेलापन"),
        shayariItem(291, "जिनकी ख़ातिर हमने अपनों से मुँह मोड़ा,\nआख़िर में उन्हीं से मुँह की खानी पड़ी।", "_ शायरी", cat, "पछतावा"),
        shayariItem(292, "मेरी वफ़ाओं का हिसाब वक़्त ख़ुद करेगा,\nआज तुम्हारा दिन है कल मेरा भी आएगा।", "_ शायरी", cat, "हिसाब"),
        shayariItem(293, "साफ़ दिखता था झूठ तेरी आँखों में,\nफिर भी हमने प्यार की खातिर यकीन कर लिया।", "_ शायरी", cat, "यकीन"),
        shayariItem(294, "दिल में रहकर दिल ही तोड़ दिया,\nइससे बड़ा धोखा और क्या हो सकता है।", "_ शायरी", cat, "धोखा"),
        shayariItem(295, "जो कल तक मेरी ख़ामोशी पढ़ लेते थे,\nआज मेरी चीख़ भी उन्हें सुनाई नहीं देती।", "_ शायरी", cat, "ख़ामोशी"),
        shayariItem(296, "हमने तो फूल बिछाए थे तेरी राहों में,\nतूने बदले में काँटों का ताज पहना दिया।", "_ शायरी", cat, "राहें"),
        shayariItem(297, "चलो अच्छा हुआ जो नक़ाब उतर गया वक़्त पर,\nवरना हम उम्र भर एक धोखे से मोहब्बत करते रहते।", "_ शायरी", cat, "नक़ाब"),
        shayariItem(298, "नफ़रत तो हम आज भी नहीं करते तुमसे,\nबस अब तुम्हारी कोई बात मायने नहीं रखती।", "_ शायरी", cat, "बेरुख़ी"),
        shayariItem(299, "टूटे हुए दिल की आवाज़ कोई नहीं सुनता,\nयहाँ हर कोई सिर्फ़ मुस्कुराते चेहरे पसंद करता है।", "_ शायरी", cat, "टूटा दिल"),
        shayariItem(300, "जाओ माफ़ किया तुम्हें तेरी हर बेवफ़ाई के बाद भी,\nबस एक बात याद रखना—हर कोई हमारे जैसा नहीं मिलेगा।", "_ शायरी", cat, "अलविदा")
    )
}
